class CountedKey:
    """A key that counts every time Python compares it with another key by value."""
    comparisons = 0

    def __init__(self, number):
        self.number = number

    def __hash__(self):
        return self.number

    def __eq__(self, other):
        CountedKey.comparisons += 1
        return isinstance(other, CountedKey) and self.number == other.number


class SlowLRU:
    """The obviously correct (and slow) cache that the random test compares against."""

    def __init__(self, capacity):
        self.capacity = capacity
        self.order = []                      # least recently used first
        self.data = {}

    def get(self, key):
        if key not in self.data:
            return None
        self.order.remove(key)
        self.order.append(key)
        return self.data[key]

    def put(self, key, value):
        if key in self.data:
            self.order.remove(key)
        elif len(self.data) == self.capacity:
            del self.data[self.order.pop(0)]
        self.order.append(key)
        self.data[key] = value

