from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity):
        self._capacity = capacity
        self._items = OrderedDict()          # least recently used first, most recently used last

    def get(self, key):
        if key not in self._items:
            return None
        self._items.move_to_end(key)         # a read counts as a use
        return self._items[key]

    def put(self, key, value):
        self._items[key] = value             # a new key lands last; an existing key keeps its old place...
        self._items.move_to_end(key)         # ...so move it last: a write counts as a use too
        if len(self._items) > self._capacity:
            self._items.popitem(last=False)  # over capacity: evict the least recently used key
